package app.dayflow.markdown;
import android.content.*;import android.net.Uri;import android.os.*;import android.view.*;import android.widget.*;import androidx.appcompat.app.AppCompatActivity;import androidx.activity.OnBackPressedCallback;import org.json.*;import java.io.*;
/** Edits one explicitly granted document. The host owns identity, CAS and synchronization. */
public final class MainActivity extends AppCompatActivity {
 public android.content.SharedPreferences prefs;public NoteEditor noteState;private LinearLayout root;private Runnable back;private Uri document;private String title="";private JSONObject current;
 public void onCreate(Bundle state){getDelegate().setLocalNightMode(getIntent().getBooleanExtra("dayflow_dark",false)?androidx.appcompat.app.AppCompatDelegate.MODE_NIGHT_YES:androidx.appcompat.app.AppCompatDelegate.MODE_NIGHT_NO);super.onCreate(state);com.google.android.material.color.DynamicColors.applyToActivityIfAvailable(this,new com.google.android.material.color.DynamicColorsOptions.Builder().setContentBasedSource(getIntent().getIntExtra("dayflow_seed",0xff386a5c)).build());prefs=getSharedPreferences("settings",0);if(state==null)prefs.edit().putInt("note_font_size",getIntent().getIntExtra("dayflow_font_size",17)).putBoolean("compact_ui",getIntent().getBooleanExtra("dayflow_compact",false)).apply();root=Ui.column(this);root.setBackgroundColor(Ui.surface(this));setContentView(root);androidx.core.view.WindowCompat.getInsetsController(getWindow(),root).setAppearanceLightStatusBars(!getIntent().getBooleanExtra("dayflow_dark",false));androidx.core.view.WindowCompat.getInsetsController(getWindow(),root).setAppearanceLightNavigationBars(!getIntent().getBooleanExtra("dayflow_dark",false));androidx.core.view.ViewCompat.setOnApplyWindowInsetsListener(root,(v,insets)->{androidx.core.graphics.Insets bars=insets.getInsets(androidx.core.view.WindowInsetsCompat.Type.systemBars()|androidx.core.view.WindowInsetsCompat.Type.ime());root.setPadding(bars.left,bars.top,bars.right,bars.bottom);return androidx.core.view.WindowInsetsCompat.CONSUMED;});getOnBackPressedDispatcher().addCallback(this,new OnBackPressedCallback(true){public void handleOnBackPressed(){if(back!=null)back.run();else finish();}});if(!"app.dayflow".equals(getCallingPackage())||getIntent().getIntExtra("dayflow_protocol",0)!=1){message("请从日栖笔记打开本插件");return;}document=getIntent().getData();if(document==null){message("未提供本次文档");return;}new Thread(()->{try{String content;try(InputStream in=getContentResolver().openInputStream(document)){content=MarkdownFiles.read(in);}JSONObject note=new JSONObject().put("id",getIntent().getStringExtra("dayflow_id")).put("revision",getIntent().getStringExtra("dayflow_revision")).put("kind","note").put("title",getIntent().getStringExtra("dayflow_title")).put("content",content).put("content_format","markdown");if(state!=null&&state.getBoolean("restore_editor"))try(InputStream snapshot=new FileInputStream(new File(getCacheDir(),"editor-state.json"))){JSONObject restored=new JSONObject(MarkdownFiles.read(snapshot));if(restored.optString("id").equals(note.optString("id")))note=restored;}catch(Exception ignored){}current=note;Data.attach(this,note);final JSONObject opened=note;runOnUiThread(()->{if(!isDestroyed())edit(opened);});}catch(Exception e){runOnUiThread(()->message("无法打开笔记："+e.getMessage()));}},"markdown-open").start();}
 public LinearLayout editorPage(String label,Runnable onBack){root.removeAllViews();back=onBack;LinearLayout page=Ui.column(this);root.addView(page,new LinearLayout.LayoutParams(-1,-1));return page;}
 public LinearLayout fullPage(String label,Runnable onBack){root.removeAllViews();back=onBack;ScrollView scroll=new ScrollView(this);LinearLayout page=Ui.padded(this);scroll.addView(page);root.addView(scroll,new LinearLayout.LayoutParams(-1,-1));return page;}
 public void edit(JSONObject r){noteState=new NoteEditor(this,r);}public void home(){finish();}public void changed(){}public void message(String text){Toast.makeText(this,text==null?"操作失败":text,Toast.LENGTH_LONG).show();}
 void wrote(JSONObject note)throws Exception{setResult(RESULT_CANCELED);java.security.MessageDigest digest=java.security.MessageDigest.getInstance("SHA-256");try(OutputStream raw=getContentResolver().openOutputStream(document,"wt");OutputStream out=new java.security.DigestOutputStream(raw,digest);Writer writer=new OutputStreamWriter(out,java.nio.charset.StandardCharsets.UTF_8)){writer.write(note.optString("content"));}String hash=android.util.Base64.encodeToString(digest.digest(),android.util.Base64.NO_WRAP);Bundle request=new Bundle();request.putString("title",note.optString("title"));request.putString("sha256",hash);request.putString("document_token",getIntent().getStringExtra("dayflow_document_token"));Bundle result=getContentResolver().call(Uri.parse("content://app.dayflow.api"),"commit_document",null,request);if(result==null||result.getInt("status",500)!=200)throw new IOException(result==null?"主应用未响应":result.getString("error","保存失败"));JSONObject saved=new JSONObject(result.getString("json"));note.put("id",saved.getString("id")).put("revision",saved.getString("revision")).put("title",saved.getString("title"));title=note.optString("title");setResult(RESULT_OK,new Intent().putExtra("dayflow_title",title).putExtra("dayflow_sha256",hash).putExtra("dayflow_font_size",prefs.getInt("note_font_size",17)));if(!saved.optString("warning").isEmpty())message(saved.optString("warning"));if(saved.optBoolean("conflict"))message("原笔记已更新，本次内容保留为冲突副本");}
 public void exportMarkdown(JSONObject r){try{MarkdownFiles.update(this,r);startActivityForResult(new Intent(Intent.ACTION_CREATE_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("text/markdown").putExtra(Intent.EXTRA_TITLE,MarkdownFiles.filename(r)),107);}catch(Exception e){message(e.getMessage());}}
 protected void onActivityResult(int code,int result,Intent data){super.onActivityResult(code,result,data);if(code==107&&result==RESULT_OK&&data!=null&&data.getData()!=null)try(InputStream in=getContentResolver().openInputStream(document);OutputStream out=getContentResolver().openOutputStream(data.getData(),"wt")){byte[] buffer=new byte[8192];int n;while((n=in.read(buffer))!=-1)out.write(buffer,0,n);message("已导出 .md");}catch(Exception e){message(e.getMessage());}}
 protected void onSaveInstanceState(Bundle state){if(noteState!=null)try{android.util.AtomicFile file=new android.util.AtomicFile(new File(getCacheDir(),"editor-state.json"));FileOutputStream out=null;try{out=file.startWrite();Writer writer=new OutputStreamWriter(out,java.nio.charset.StandardCharsets.UTF_8);writer.write(noteState.draft().toString());writer.flush();file.finishWrite(out);state.putBoolean("restore_editor",true);}catch(Exception e){if(out!=null)file.failWrite(out);}}catch(Exception ignored){}super.onSaveInstanceState(state);}
 protected void onDestroy(){if(noteState!=null)noteState.close();noteState=null;Data.detach(this);super.onDestroy();}
 protected void onPause(){if(noteState!=null)noteState.keepDraft();super.onPause();}
}
